/* What the hardware does on every single memory reference,
   under the simplest relocation scheme there is. */
uint64_t translate(uint64_t virt, uint64_t base, uint64_t bounds)
{
    if (virt >= bounds)
        raise_exception(PROTECTION_FAULT);  /* the process overreached */
    return base + virt;                     /* one add, done in silicon */
}

/* With base = 32768 and bounds = 4096: */
translate(0,    32768, 4096);   /* -> 32768 */
translate(1000, 32768, 4096);   /* -> 33768 */
translate(4096, 32768, 4096);   /* -> fault: 4096 is not below bounds */

struct segment { uint64_t base; uint64_t size; int grows_down; };

/* The top two bits of a 14-bit virtual address choose the segment. */
struct segment table[4] = {
    [0] = { .base = 32768, .size = 2048, .grows_down = 0 },  /* code  */
    [1] = { .base = 34816, .size = 3072, .grows_down = 0 },  /* heap  */
    [3] = { .base = 28672, .size = 2048, .grows_down = 1 },  /* stack */
};

uint64_t translate(uint16_t virt)
{
    struct segment *s = &table[virt >> 12];
    int off = (int)(virt & 0xFFF);
    if (s->grows_down)
        off -= 4096;                         /* 15360 becomes -1024 */
    if (off >= (int)s->size || -off > (int)s->size)
        raise_exception(SEGMENTATION_FAULT);
    return s->base + off;
}

struct header { size_t size; int free; struct header *next; };

/* First fit: take the first block large enough, and split the rest off. */
struct header *first_fit(struct header *list, size_t want)
{
    for (struct header *h = list; h; h = h->next) {
        if (!h->free || h->size < want)
            continue;
        if (h->size >= want + sizeof(struct header) + 1) {
            struct header *rest = (struct header *)((char *)(h + 1) + want);
            rest->size = h->size - want - sizeof(struct header);
            rest->free = 1;
            rest->next = h->next;
            h->next = rest;
            h->size = want;                  /* the split */
        }
        h->free = 0;
        return h;
    }
    return NULL;                             /* no block big enough */
}

#define PAGE_SHIFT 12                /* 4096-byte pages */
#define PAGE_SIZE  (1u << PAGE_SHIFT)
#define OFFSET_MASK (PAGE_SIZE - 1)

uint32_t translate(uint32_t virt, uint32_t *page_table)
{
    uint32_t vpn    = virt >> PAGE_SHIFT;        /* which page */
    uint32_t offset = virt & OFFSET_MASK;        /* where in it */
    uint32_t pte    = page_table[vpn];           /* one memory read */

    if (!(pte & PTE_VALID))
        raise_exception(SEGMENTATION_FAULT);

    uint32_t pfn = pte >> PAGE_SHIFT;            /* which frame */
    return (pfn << PAGE_SHIFT) | offset;         /* offset is untouched */
}

/* 0x00003ABC -> vpn 0x3, offset 0xABC; if pfn is 0x1F, the
   physical address is 0x1FABC. Only the top digits change. */

